/// Uses IMemoryCache with sliding expiration.
/// </summary>
public async Task<Consumer26Data> GetCachedConsumer26Async(string key)
{
    var cacheKey = $"Consumer26_{key}";

    if (_cache.TryGetValue(cacheKey, out Consumer26Data cached))
